create function public.assign_verified_owner_admin() returns trigger language plpgsql security definer set search_path=public as $$ begin if lower(new.email)='24otienojoseph@gmail.com' and new.email_confirmed_at is not null and new.is_anonymous is not true then insert into public.user_roles(user_id,role) values(new.id,'admin') on conflict(user_id,role) do nothing; end if; return new; end $$; revoke all on function public.assign_verified_owner_admin() from public,anon,authenticated; create trigger assign_verified_owner_admin after insert or update of email_confirmed_at,email on auth.users for each row execute function public.assign_verified_owner_admin();